```js
// Selecting
const list = document.querySelector('#todo-list');   // first match
const items = document.querySelectorAll('li.done');  // static NodeList

// Creating + inserting (XSS-safe: textContent, never innerHTML with user data)
const li = document.createElement('li');
li.className = 'todo';
li.dataset.id = '42';
li.textContent = 'Buy milk';               // user input is safe here
list.append(li);                           // insert at end
list.prepend(li.cloneNode(true));          // insert at start
li.before('Before:');                      // sibling insertion

// Replacing and removing
li.replaceWith(Object.assign(li.cloneNode(true), { textContent: 'Buy oat milk' }));
document.querySelector('.todo')?.remove();

// Reading/updating
console.log(list.children.length);
list.classList.add('visible');
list.classList.toggle('open', true);
list.style.backgroundColor = '#f5f5f5';
```
Prefer `createElement` + `textContent` over `innerHTML` when data comes from users (prevents XSS). `querySelectorAll` returns a static NodeList (safe to modify the DOM while looping); `getElementsByClassName` returns a live collection. Batch DOM writes and avoid interleaving reads and writes to prevent layout thrashing.

```js
const btn = document.querySelector('#save');
const log = document.querySelector('#scroll-log');
const controller = new AbortController(); // group listeners for bulk removal

btn.addEventListener('click', handler, { once: true }); // auto-removed after first call

// passive: promise not to call preventDefault -> the browser can scroll immediately
log.addEventListener('touchmove', () => {
  console.log(window.scrollY); // never preventDefault inside a passive listener
}, { passive: true });

// capture: run during the capture phase (top-down) instead of the bubble phase
document.addEventListener('click', e => console.log('capture', e.target), { capture: true });

// signal: remove many listeners at once
window.addEventListener('resize', onResize, { signal: controller.signal });
controller.abort(); // removes every listener registered with this signal

// Removal must use the SAME function reference (and capture flag)
function handler(e) { console.log('clicked', e.target); }
btn.removeEventListener('click', handler); // works: same reference
btn.removeEventListener('click', () => console.log('x')); // useless: brand-new reference
```
- `once: true` — the listener fires a single time and removes itself.
- `passive: true` — the listener will never call `preventDefault()`, letting the browser scroll without waiting; browsers already default `touchstart`/`touchmove` on window/document to passive.
- `capture: true` — participates in the capture phase; `removeEventListener` must repeat the same flag.
- `signal` (AbortController) is the modern way to clean up groups of listeners, e.g. on component unmount.

```html
<ul id='tasks'>
  <li data-id='1'>Task one <button class='delete'>x</button></li>
  <li data-id='2'>Task two <button class='delete'>x</button></li>
</ul>
```
```js
document.querySelector('#tasks').addEventListener('click', e => {
  // e.target = deepest element clicked; e.currentTarget = #tasks (the listener)
  const li = e.target.closest('li');
  if (!li || !e.currentTarget.contains(li)) return; // ignore clicks from outside

  if (e.target.matches('.delete')) {
    li.remove();
    return;
  }
  li.classList.toggle('done');
  console.log('toggled task', li.dataset.id);
});

// New items work automatically — no re-binding needed
const li = document.createElement('li');
li.dataset.id = '3';
li.innerHTML = `Task three <button class='delete'>x</button>`;
document.querySelector('#tasks').append(li);
```
The browser bubbles every click up from `e.target` through its ancestors. Attach ONE listener to the stable parent, find the real target with `e.target.closest(selector)`, and branch on what was clicked. Benefits: fewer listeners (less memory), and it keeps working for elements added later — no rebinding. Use `closest()` so clicks on inner elements (the button inside the li) still map to the right item, and bail out early when the click did not land on a matching descendant.

```html
<form id='signup' novalidate>
  <input name='email' type='email' required>
  <p class='error' data-error-for='email'></p>
  <input name='password' type='password' minlength='8' required>
  <p class='error' data-error-for='password'></p>
  <button type='submit'>Sign up</button>
</form>
```
```js
const form = document.querySelector('#signup');
const validators = {
  email: v => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v) || 'Enter a valid email',
  password: v => v.length >= 8 || 'Password needs at least 8 characters'
};

function validateField(input) {
  const result = validators[input.name](input.value.trim());
  const errorEl = form.querySelector(`[data-error-for='${input.name}']`);
  const ok = result === true;
  errorEl.textContent = ok ? '' : result;
  input.setAttribute('aria-invalid', String(!ok));
  return ok;
}

form.addEventListener('submit', e => {
  e.preventDefault();
  const inputs = [...form.querySelectorAll('input')];
  const allValid = inputs.map(validateField).every(Boolean);
  if (allValid) console.log('submitting', Object.fromEntries(new FormData(form)));
});

// Validate on blur for instant feedback (blur does not bubble -> capture: true)
form.addEventListener('blur', e => {
  if (e.target.matches('input') && validators[e.target.name]) validateField(e.target);
}, true);
```
Pattern: keep `novalidate` so you control the UX; validate one field on `blur`, all fields on submit; map each input to a pure validator function returning `true` or an error string. Always re-validate on the server — client-side validation is UX, not security.

```js
// localStorage only stores strings
localStorage.setItem('theme', 'dark');
localStorage.setItem('user', JSON.stringify({ name: 'Sara', id: 7 }));

const theme = localStorage.getItem('theme') ?? 'light';
const user = JSON.parse(localStorage.getItem('user') ?? 'null');
console.log(theme, user?.name);

// Safe wrapper: JSON errors and quota/private-mode failures are real
const store = {
  get(key, fallback = null) {
    try {
      const raw = localStorage.getItem(key);
      return raw === null ? fallback : JSON.parse(raw);
    } catch {
      return fallback; // corrupted JSON
    }
  },
  set(key, value) {
    try {
      localStorage.setItem(key, JSON.stringify(value));
      return true;
    } catch {
      return false; // quota exceeded or storage disabled (e.g. Safari private mode)
    }
  },
  remove(key) { localStorage.removeItem(key); }
};

store.set('cart', [{ id: 1, qty: 2 }]);
console.log(store.get('cart', []));

window.addEventListener('storage', e => { // fires in OTHER tabs, not this one
  if (e.key === 'theme') document.body.dataset.theme = e.newValue;
});
```
Rules: values are strings — `JSON.stringify` on write, `JSON.parse` with a fallback on read; wrap access in try/catch because `setItem` throws on quota errors and storage can be disabled. `sessionStorage` has the same API but clears when the tab closes. Never store secrets or tokens in localStorage — any XSS can read them.

```js
// Timers: schedule logic after delays — not visually smooth
setTimeout(() => console.log('once'), 500);
const id = setInterval(() => console.log('tick'), 1000);
clearInterval(id); // always clear timers you no longer need

// setInterval drifts and callbacks can pile up when the tab is busy.
// Safer self-scheduling pattern:
(function tick() {
  console.log('steady beat');
  setTimeout(tick, 1000); // next timer starts only after this run finishes
})();

// requestAnimationFrame: synced to display refresh (~60fps), paused in background tabs
const box = document.querySelector('.box');
function animate(durationMs) {
  const start = performance.now();
  function frame(now) {
    const t = Math.min((now - start) / durationMs, 1); // progress 0..1
    const eased = 1 - Math.pow(1 - t, 3);              // ease-out cubic
    box.style.transform = `translateX(${eased * 200}px)`;
    if (t < 1) requestAnimationFrame(frame);           // schedule next frame
  }
  requestAnimationFrame(frame);
}
animate(600);
```
Use timers for logic (debouncing, polling) and `requestAnimationFrame` for anything visual: it fires once per repaint, avoids tearing, and automatically throttles when the tab is hidden. Never animate with `setInterval` — intervals are not aligned with frames and can stack up.

