```js
// debounce: run ONCE after calls stop for `wait` ms (search inputs, autosave)
function debounce(fn, wait = 300) {
  let timer;
  return function debounced(...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), wait);
  };
}

// throttle: run at most once per `limit` ms (scroll, mousemove)
function throttle(fn, limit = 200) {
  let lastCall = 0;
  return function throttled(...args) {
    const now = Date.now();
    if (now - lastCall >= limit) {
      lastCall = now;
      fn.apply(this, args);
    }
  };
}

const search = document.querySelector('#search');
search.addEventListener('input', debounce(e => {
  fetch(`/api/suggest?q=${encodeURIComponent(e.target.value)}`).then(r => r.json());
}, 250));

window.addEventListener('scroll', throttle(() => {
  console.log('scroll position checked at most 5x per second');
}, 200), { passive: true });
```
- Debounce waits for silence: ideal when only the FINAL value matters (autocomplete, autosave, resize-end).
- Throttle enforces a steady maximum rate: ideal for continuous streams you must sample (scroll, drag, mousemove).
- Both wrap the handler and rely on closures for state. Return a `function` (not an arrow) so `this` and arguments pass through, and keep the timer handle around if you need to cancel pending calls.

