  height: 100svh;  /* small viewport: never taller than the visible area */
}
@supports (height: 100dvh) {
  .hero { height: 100dvh; }  /* tracks the CURRENT visible viewport */
}

/* JS fallback for legacy browsers: */
.hero { height: calc(var(--vh, 1vh) * 100); }
