**Prevention:** default full-screen sections to `min-height: 100svh`; reserve `dvh` for elements that must truly track the visible viewport; test in Chrome DevTools device mode with a mobile toolbar profile.

```js
// Currying: f(a, b, c) -> f(a)(b)(c)
const curry = fn => {
  const curried = (...args) =>
    args.length >= fn.length
      ? fn(...args)
      : (...next) => curried(...args, ...next);
  return curried;
};

const add3 = (a, b, c) => a + b + c;
const cAdd = curry(add3);
console.log(cAdd(1)(2)(3), cAdd(1, 2)(3), cAdd(1)(2, 3)); // 6 6 6

// Partial application: fix SOME arguments up front
const withSlash = (base, path) => `${base}/${path}`;
const api = withSlash.bind(null, 'https://api.example.com');
console.log(api('users')); // https://api.example.com/users

// Practical pipeline: reusable, testable units
const prop = key => obj => obj[key];
const byPrice = min => list => list.filter(p => p.price >= min);
const names = list => list.map(prop('name'));

const expensiveNames = products => names(byPrice(500)(products));
console.log(expensiveNames([{ name: 'M1', price: 100 }, { name: 'M2', price: 900 }]));
// ['M2']
```
