```js
// A generator pauses at each yield and resumes on demand
function* countdown(from) {
  for (let i = from; i > 0; i--) yield i;
  return 'liftoff'; // visible via .next(), ignored by for...of
}

const gen = countdown(3);
console.log(gen.next());        // { value: 3, done: false }
console.log(gen.next());        // { value: 2, done: false }
console.log([...countdown(3)]); // [3, 2, 1] — generators are iterable

// Infinite lazy sequence: values are computed only when pulled
function* fibonacci() {
  let [a, b] = [0, 1];
  while (true) { yield a; [a, b] = [b, a + b]; }
}

function* take(iterable, n) {
  for (const value of iterable) {
    if (n-- <= 0) return;
    yield value;
  }
}
console.log([...take(fibonacci(), 8)]); // [0, 1, 1, 2, 3, 5, 8, 13]

// Practical: paginate an API lazily
async function* fetchPages(url) {
  let page = 1;
  while (true) {
    const res = await fetch(`${url}?page=${page++}`);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const items = await res.json();
    if (!items.length) return;
    yield* items; // delegate to another iterable
  }
}
for await (const item of fetchPages('/api/logs')) process(item);
```
`function*` defines a generator; calling it returns an iterator whose `next()` runs until the next `yield`. Generators produce values lazily (ideal for infinite or expensive sequences), delegate with `yield*`, and async generators make paginated streams trivial. Remember: `for...of` ignores the generator's `return` value.

