shallow.nested.b = 99;
console.log(original.nested.b); // 99 — changed too! Same reference

// 2. structuredClone: TRUE deep copy, handles Dates, Maps, Sets, cycles
const deep = structuredClone(original);
deep.nested.b = 42;
console.log(original.nested.b); // 99 — unaffected by the deep edit

// 3. JSON round-trip: deep but LOSSY — do not use for real data
const lossy = JSON.parse(JSON.stringify(original));
console.log(lossy.when); // '1970-01-01T00:00:00.000Z' — Date became a string
